/**
 * Memory - Time-decaying memory storage
 *
 * Stores information that fades over time, like last known positions
 * or remembered events. Each memory has a decay time after which
 * it becomes unavailable.
 *
 * **Usage**
 *
 * ```js
 * // Remember something for 30 seconds
 * memory.remember('lastSeenPosition', targetPos, 30);
 *
 * // Recall it (returns null after decay)
 * const pos = memory.recall('lastSeenPosition');
 *
 * // Check confidence (1.0 = fresh, 0.0 = about to expire)
 * const confidence = memory.getConfidence('lastSeenPosition');
 * ```
 *
 * @module @three-blocks/pro/ai/Memory
 * @class Memory
 * @short Time-decaying memory storage
 * @category AI
 * @tags AI, Memory, Perception
 */
export class Memory {
    /**
     * Create a new Memory instance.
     *
     * @param {number} [defaultDecayTime=30] - Default decay time in seconds.
     */
    constructor(defaultDecayTime?: number);
    /**
     * @type {number}
     * @private
     */
    private _defaultDecayTime;
    /**
     * @type {Map<string, { value: any, createdAt: number, decayTime: number }>}
     * @private
     */
    private _memories;
    /**
     * Current time reference.
     * @type {number}
     * @private
     */
    private _currentTime;
    /**
     * Store a memory that will decay over time.
     *
     * @param {string} key - Memory key.
     * @param {any} value - Value to remember.
     * @param {number} [decayTime] - Time in seconds before decay (uses default if not specified).
     * @returns {Memory} This instance for chaining.
     */
    remember(key: string, value: any, decayTime?: number): Memory;
    /**
     * Recall a memory if it hasn't decayed.
     *
     * @param {string} key - Memory key.
     * @returns {any|null} The remembered value, or null if decayed/never set.
     */
    recall(key: string): any | null;
    /**
     * Get the confidence level of a memory (1.0 = fresh, 0.0 = expired).
     *
     * @param {string} key - Memory key.
     * @returns {number} Confidence from 0.0 to 1.0, or 0 if not found.
     */
    getConfidence(key: string): number;
    /**
     * Check if a memory exists and hasn't decayed.
     *
     * @param {string} key - Memory key.
     * @returns {boolean} True if memory exists and is valid.
     */
    has(key: string): boolean;
    /**
     * Forget a specific memory.
     *
     * @param {string} key - Memory key to forget.
     * @returns {boolean} True if the memory existed.
     */
    forget(key: string): boolean;
    /**
     * Clear all memories.
     *
     * @returns {Memory} This instance for chaining.
     */
    clear(): Memory;
    /**
     * Update memory time and clean up expired memories.
     * Called each frame.
     *
     * @param {number} delta - Time delta in seconds.
     * @returns {Memory} This instance for chaining.
     */
    update(delta: number): Memory;
    /**
     * Get the age of a memory in seconds.
     *
     * @param {string} key - Memory key.
     * @returns {number} Age in seconds, or Infinity if not found.
     */
    getAge(key: string): number;
    /**
     * Refresh a memory's timestamp without changing its value.
     *
     * @param {string} key - Memory key to refresh.
     * @returns {boolean} True if the memory existed and was refreshed.
     */
    refresh(key: string): boolean;
}
